import type { FC } from 'react';

// Ambient module declarations for the auto-generated Framer components.
// These JS files ship without type definitions; we declare them here so the
// TypeScript compiler knows what each module exports without needing DefinitelyTyped.
//
// The wildcard (*) in the module specifier matches any leading path prefix, so
// both relative imports ("../../framer/ImageWrapper.js") and aliased imports
// ("@/framer/ImageWrapper.js") resolve to the same declaration.

declare module '*framer/ImageWrapper.js' {
  export const BellLamp: FC<any>;
  export const Plant0: FC<any>;
  export const Plant1: FC<any>;
  export const Plant2: FC<any>;
  export const Plant3: FC<any>;
  export const Plant4: FC<any>;
  export const Eggchair: FC<any>;
  export const Pen: FC<any>;
  export const Headphones: FC<any>;
  export const Chair: FC<any>;
  export const BackwallLight: FC<any>;
}

declare module '*framer/Notebook-Large-POCp.js' {
  const C: FC<any>;
  export default C;
}

declare module '*framer/Imaged-Post-It-1vlf.js' {
  const C: FC<any>;
  export default C;
}

declare module '*framer/NoteBook-Open-NHDl.js' {
  const C: FC<any>;
  export default C;
}
